}

function createTriangularPrismGeometry(sideLength, prismLength) {
  const geometry = new THREE.BufferGeometry();

  // Height of equilateral triangle
  const h = (Math.sqrt(3) / 2) * sideLength;

  // Vertices: triangular cross-section in YZ plane, extruded along X
  const vertices = new Float32Array([
    // Front face (x = 0)
    0, h / 2, 0,              // 0: top
    0, -h / 2, -sideLength / 2, // 1: bottom-left
    0, -h / 2, sideLength / 2,  // 2: bottom-right

    // Back face (x = prismLength)
    prismLength, h / 2, 0,              // 3: top
    prismLength, -h / 2, -sideLength / 2, // 4: bottom-left
    prismLength, -h / 2, sideLength / 2   // 5: bottom-right
  ]);

  const indices = new Uint32Array([
    // Front triangle
    0, 2, 1,
    // Back triangle
    3, 4, 5,
    // Top rectangle
    0, 3, 5, 0, 5, 2,
    // Bottom rectangle
    1, 4, 3, 1, 3, 0,
    // Left rectangle
    0, 1, 4, 0, 4, 3,
    // Right rectangle
    2, 5, 4, 2, 4, 1
  ]);

  geometry.setAttribute('position', new THREE.BufferAttribute(vertices, 3));
  geometry.setIndex(new THREE.BufferAttribute(indices, 1));
  geometry.computeVertexNormals();
  geometry.center();

  return geometry;
}

